import{_ as n,o as a,c as e,S as l}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse('{"title":"Vue中组件的设计","description":"","frontmatter":{"title":"Vue中组件的设计","date":"2020-07-30 22:08","comments":true,"archives":2020,"tags":["frontend","vue"]},"headers":[],"relativePath":"posts/2020-07-30-vue-components/index.md","filePath":"posts/2020/2020-07-30-vue-components.md"}'),p={name:"posts/2020-07-30-vue-components/index.md"};function o(t,s,c,r,i,d){return a(),e("div",null,[...s[0]||(s[0]=[l(`<p>Vue 中组件设计经常遇到复合组件的问题，例如下拉菜单，下拉菜单中我们不仅要实现<code>select</code>元素的功能，还要实现<code>option</code>元素的功能，这样才是一个完整的下拉菜单组件。</p><h2 id="复合组件中的数据相互访问" tabindex="-1">复合组件中的数据相互访问 <a class="header-anchor" href="#复合组件中的数据相互访问" aria-label="Permalink to &quot;复合组件中的数据相互访问&quot;">​</a></h2><p>复合组件中的数据访问是设计组件的一个重要议题，设计不好会严重影响组件的灵活性。我们拿 Element UI 的组件来举个例子：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">el-select</span><span style="color:#6F42C1;"> v-model</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;value&quot;</span><span style="color:#6F42C1;"> placeholder</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;请选择&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">el-option</span></span>
<span class="line"><span style="color:#6F42C1;">    v-for</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;item in options&quot;</span></span>
<span class="line"><span style="color:#6F42C1;">    :key</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;item.value&quot;</span></span>
<span class="line"><span style="color:#6F42C1;">    :label</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;item.label&quot;</span></span>
<span class="line"><span style="color:#6F42C1;">    :value</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;item.value&quot;</span></span>
<span class="line"><span style="color:#24292E;">  &gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;/</span><span style="color:#22863A;">el-option</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">el-select</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p>这是一个经典的例子，但是实际使用过程中，我们可能会二次封装组件,例如我们需要给<code>el-option</code>加一些事件或者样式，那我们的代码会变成这样：</p><div class="language-html line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">&lt;</span><span style="color:#22863A;">el-select</span><span style="color:#6F42C1;"> v-model</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;value&quot;</span><span style="color:#6F42C1;"> placeholder</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;请选择&quot;</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;</span><span style="color:#22863A;">styled-el-option</span></span>
<span class="line"><span style="color:#6F42C1;">    v-for</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;item in options&quot;</span></span>
<span class="line"><span style="color:#6F42C1;">    :key</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;item.value&quot;</span></span>
<span class="line"><span style="color:#6F42C1;">    :label</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;item.label&quot;</span></span>
<span class="line"><span style="color:#6F42C1;">    :value</span><span style="color:#24292E;">=</span><span style="color:#032F62;">&quot;item.value&quot;</span></span>
<span class="line"><span style="color:#24292E;">  &gt;</span></span>
<span class="line"><span style="color:#24292E;">  &lt;/</span><span style="color:#22863A;">styled-el-option</span><span style="color:#24292E;">&gt;</span></span>
<span class="line"><span style="color:#24292E;">&lt;/</span><span style="color:#22863A;">el-select</span><span style="color:#24292E;">&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><p><code>styled-el-option</code> 是我们二次封装的组件，里面包含了<code>el-option</code>组件。如果我们使用<code>$parent</code>在<code>el-option</code>组件中访问<code>el-select</code>组件的话，二次封装的情况下就会出错。 因为<code>el-option</code>的父组件不再是<code>el-select</code>，而是<code>styled-el-option</code>。正确的数据访问方式是使用<code>provide</code> 和 <code>inject</code>。</p><h2 id="子组件访问父组件" tabindex="-1">子组件访问父组件 <a class="header-anchor" href="#子组件访问父组件" aria-label="Permalink to &quot;子组件访问父组件&quot;">​</a></h2><p>首先我们需要在父附件中这样定义：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">provide</span><span style="color:#24292E;">: </span><span style="color:#D73A49;">function</span><span style="color:#24292E;"> () {</span></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#032F62;">    &#39;select&#39;</span><span style="color:#24292E;">: </span><span style="color:#005CC5;">this</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>然后在子组件中使用<code>inject</code>:</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">inject</span><span style="color:#24292E;">: [</span><span style="color:#032F62;">&#39;select&#39;</span><span style="color:#24292E;">];</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这样子组件就可以访问父组件了，使用<code>provide</code>的好处是不用担心复合组件中的再封装问题，Vue 会自动向上查找。</p><h2 id="父组件访问子组件" tabindex="-1">父组件访问子组件 <a class="header-anchor" href="#父组件访问子组件" aria-label="Permalink to &quot;父组件访问子组件&quot;">​</a></h2><p>Vue 中并没有提供非常方便的查找子组件的功能， 所以目前的方法是在父组件中存储子组件的实例。</p><p>父组件中定义数据：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">data</span><span style="color:#24292E;">: </span><span style="color:#D73A49;">function</span><span style="color:#24292E;"> () {</span></span>
<span class="line"><span style="color:#D73A49;">  return</span><span style="color:#24292E;"> {</span></span>
<span class="line"><span style="color:#24292E;">    options: []</span></span>
<span class="line"><span style="color:#24292E;">  }</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>子组件通过<code>inject</code>可以访问父组件，所以：</p><div class="language-js line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6F42C1;">created</span><span style="color:#24292E;">() {</span></span>
<span class="line"><span style="color:#005CC5;">  this</span><span style="color:#24292E;">.select.options.</span><span style="color:#6F42C1;">push</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">this</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>在创建组件的时候同时传入父组件的<code>data</code>字段中。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>灵活的设计组件才能在实际开发中更方便的使用，一些第三方组件开发的时候没有考虑到二次封装的可能性，直接通过<code>$parent</code>和<code>$children</code>进行数据的更新。导致可用性大大降低。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://vuejs.org/v2/guide/components-edge-cases.html#Dependency-Injection" target="_blank" rel="noreferrer">Dependency Injection</a></p>`,24)])])}const y=n(p,[["render",o]]);export{b as __pageData,y as default};
